from __future__ import annotations

import json
import re
import shutil
import subprocess
import tempfile
from pathlib import Path


_USER_STORY_HEADER_RE = re.compile(r"^User Story:\s*(.+?)\s*$")
_USER_STORY_ID_RE = re.compile(r"\bUser Story\s+(\d+)\b", re.IGNORECASE)
_PAGE_RE = re.compile(r"^Page\s+\d+\s+of\s+\d+\s*$")
_AZURE_WI_ID_RE = re.compile(r"/edit/(\d+)(?:[/?#].*)?$")
_DOCX_EXTS = {".docx", ".docm", ".dotx", ".dotm"}
_PDF_EXTS = {".pdf"}
_MD_EXTS = {".md", ".markdown", ".mdown"}


def _extract_pdf_text(pdf_path: Path) -> str:
    try:
        result = subprocess.run(
            ["pdftotext", "-layout", str(pdf_path), "-"],
            check=True,
            capture_output=True,
            text=True,
        )
    except (FileNotFoundError, subprocess.CalledProcessError):
        return ""
    return result.stdout


def _extract_pdf_story_ids(pdf_path: Path) -> list[str]:
    try:
        result = subprocess.run(
            ["pdftohtml", "-stdout", "-xml", str(pdf_path)],
            check=True,
            capture_output=True,
            text=True,
        )
    except (FileNotFoundError, subprocess.CalledProcessError):
        return []

    story_ids: list[str] = []
    for line in result.stdout.splitlines():
        if "User Story:" not in line or "href=\"" not in line:
            continue
        href_match = re.search(r'href="([^"]+)"', line)
        if not href_match:
            continue
        wi_match = _AZURE_WI_ID_RE.search(href_match.group(1))
        if wi_match:
            story_ids.append(f"US-{int(wi_match.group(1)):07d}")
    return story_ids


def _extract_docx_text(docx_path: Path) -> str:
    libreoffice = shutil.which("libreoffice") or shutil.which("soffice")
    if not libreoffice:
        return ""
    with tempfile.TemporaryDirectory() as tmpdir:
        tmpdir_path = Path(tmpdir)
        try:
            subprocess.run(
                [
                    libreoffice,
                    "--headless",
                    "--convert-to",
                    "txt:Text",
                    "--outdir",
                    str(tmpdir_path),
                    str(docx_path),
                ],
                check=True,
                capture_output=True,
                text=True,
            )
        except subprocess.CalledProcessError:
            return ""
        txt_path = tmpdir_path / f"{docx_path.stem}.txt"
        if txt_path.exists():
            return txt_path.read_text(encoding="utf-8", errors="ignore")
        for candidate in tmpdir_path.glob("*.txt"):
            return candidate.read_text(encoding="utf-8", errors="ignore")
    return ""


def _read_text_source(path: Path) -> str:
    suffix = path.suffix.lower()
    if suffix in _PDF_EXTS:
        return _extract_pdf_text(path)
    if suffix in _DOCX_EXTS:
        return _extract_docx_text(path)
    if suffix in _MD_EXTS:
        return path.read_text(encoding="utf-8")
    return ""


def _normalize_block_text(lines: list[str]) -> str:
    cleaned: list[str] = []
    for line in lines:
        text = line.strip()
        if not text:
            continue
        if _PAGE_RE.match(text):
            continue
        if text == "ADO User Story Export":
            continue
        cleaned.append(text)
    return " ".join(cleaned).strip()


def _extract_user_story_id(*texts: str) -> str | None:
    for text in texts:
        match = _USER_STORY_ID_RE.search(text)
        if match:
            return f"US-{int(match.group(1)):07d}"
    return None


def _parse_user_stories(text: str, source: Path, story_ids: list[str] | None = None) -> list[dict]:
    requirements: list[dict] = []
    lines = text.splitlines()
    i = 0
    rid = 1
    story_index = 0

    while i < len(lines):
        match = _USER_STORY_HEADER_RE.match(lines[i].strip())
        if not match:
            i += 1
            continue

        title = match.group(1).strip()
        i += 1
        description_lines: list[str] = []
        acceptance_lines: list[str] = []
        section = ""

        while i < len(lines):
            current = lines[i].strip()
            if _USER_STORY_HEADER_RE.match(current):
                break
            if current == "Description:":
                section = "description"
                i += 1
                continue
            if current == "Acceptance Criteria:":
                section = "acceptance"
                i += 1
                continue
            if current.startswith("Page ") and current.endswith(" of 38"):
                i += 1
                continue
            if current == "ADO User Story Export":
                i += 1
                continue

            if section == "description":
                description_lines.append(lines[i])
            elif section == "acceptance":
                acceptance_lines.append(lines[i])
            i += 1

        description = _normalize_block_text(description_lines)
        acceptance_criteria = [line.strip() for line in acceptance_lines if line.strip()]
        user_story_id = story_ids[story_index] if story_ids and story_index < len(story_ids) else None
        if not user_story_id:
            user_story_id = _extract_user_story_id(title, description, *acceptance_criteria)
        story_index += 1
        requirements.append(
            {
                "req_id": f"R-{rid:03d}",
                "title": title,
                "description": description,
                "acceptance_criteria": acceptance_criteria,
                "user_story_id": user_story_id,
            }
        )
        rid += 1

    return requirements


def _discover_prd_sources(prd_dir: Path) -> list[Path]:
    if not prd_dir.exists():
        return []
    priority = {".pdf": 0, ".docx": 1, ".docm": 1, ".dotx": 1, ".dotm": 1, ".md": 2, ".markdown": 2, ".mdown": 2}
    candidates = [p for p in prd_dir.iterdir() if p.is_file() and p.suffix.lower() in priority]
    return sorted(candidates, key=lambda p: (priority.get(p.suffix.lower(), 99), p.name.lower()))


def ingest_prd(docs_root: Path) -> Path:
    out = docs_root / "ai-generation" / "knowledge" / "requirements_index.json"
    out.parent.mkdir(parents=True, exist_ok=True)

    prd_dir = docs_root / "prd"
    reqs: list[dict] = []
    selected_source: Path | None = None

    for source in _discover_prd_sources(prd_dir):
        text = _read_text_source(source)
        if not text:
            continue
        if source.suffix.lower() in _PDF_EXTS:
            reqs = _parse_user_stories(text, source, story_ids=_extract_pdf_story_ids(source))
        elif source.suffix.lower() in _DOCX_EXTS:
            reqs = _parse_user_stories(text, source)
        else:
            rid = 1
            for line in text.splitlines():
                item = line.strip()
                if not item or item.startswith("#"):
                    continue
                reqs.append(
                    {
                        "req_id": f"R-{rid:03d}",
                        "title": item,
                        "description": item,
                        "acceptance_criteria": [],
                        "user_story_id": _extract_user_story_id(item),
                    }
                )
                rid += 1
        if reqs:
            selected_source = source
            break

    out.write_text(
        json.dumps({"version": "0.1", "requirements": reqs}, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return out

from __future__ import annotations

import json
import subprocess
from dataclasses import dataclass, asdict
from enum import Enum
from pathlib import Path

from rich.console import Console

from firmware_agent.slices.S07_Compiler.compiler import compile_system_design
from firmware_agent.slices.S09_PRD_Ingestion.prd_ingestion import ingest_prd

console = Console()


class WorkflowPhase(str, Enum):
    INIT = "init"
    WAIT_FOR_EXTERNAL_FILES = "wait_for_external_files"
    INGEST = "ingest"
    WAIT_FOR_DESIGN_REVIEW = "wait_for_design_review"
    GENERATE = "generate"
    TEST = "test"
    DONE = "done"


@dataclass
class WorkflowState:
    phase: str = WorkflowPhase.INIT.value
    last_completed_phase: str = ""
    approved_design: bool = False
    notes: str = ""


class WorkflowRunner:
    def __init__(self, project_dir: Path):
        self.project_dir = project_dir
        self.docs_root = project_dir / "Docs"
        self.state_path = self.docs_root / "ai-generation" / "workflow" / "state.json"
        self.state_path.parent.mkdir(parents=True, exist_ok=True)
        self.state = self.load_state()

    def load_state(self) -> WorkflowState:
        if self.state_path.exists():
            data = json.loads(self.state_path.read_text(encoding="utf-8") or "{}")
            return WorkflowState(**{k: data.get(k, getattr(WorkflowState(), k)) for k in WorkflowState.__dataclass_fields__})
        return WorkflowState()

    def save_state(self) -> None:
        self.state_path.write_text(json.dumps(asdict(self.state), ensure_ascii=False, indent=2), encoding="utf-8")

    def reset_state(self) -> None:
        self.state = WorkflowState()
        if self.state_path.exists():
            self.state_path.unlink()
        self.state_path.parent.mkdir(parents=True, exist_ok=True)
        self.save_state()

    def _print_banner(self, title: str) -> None:
        console.rule(f"[bold cyan]{title}[/bold cyan]")

    def _roadmap_lines(self) -> list[str]:
        return [
            "1. Initialize project",
            "2. Wait for external documents",
            "3. Ingest documents into standard format",
            "4. Review generated design",
            "5. Generate implementation artifacts",
            "6. Run module tests and report",
            "7. Finish workflow",
        ]

    def _roadmap_order(self) -> list[str]:
        return [
            WorkflowPhase.INIT.value,
            WorkflowPhase.WAIT_FOR_EXTERNAL_FILES.value,
            WorkflowPhase.INGEST.value,
            WorkflowPhase.WAIT_FOR_DESIGN_REVIEW.value,
            WorkflowPhase.GENERATE.value,
            WorkflowPhase.TEST.value,
            WorkflowPhase.DONE.value,
        ]

    def _current_stage_index(self) -> int:
        order = self._roadmap_order()
        return order.index(self.state.phase) if self.state.phase in order else 0

    def _next_stage_label(self) -> str:
        order = self._roadmap_order()
        idx = self._current_stage_index()
        if idx + 1 < len(order):
            return self._roadmap_lines()[idx + 1]
        return "Workflow complete"

    def _status_bar(self) -> str:
        total = len(self._roadmap_lines())
        current = self._current_stage_index() + 1
        label = self._roadmap_lines()[self._current_stage_index()]
