@dataclass(frozen=True)
class Issue:
    code: str
    message: str
    blocking: bool = True

    def __str__(self) -> str:
        flag = "x" if self.blocking else "!"
        return f"[{flag}] {self.code}: {self.message}"


@dataclass
class VerificationReport:
    source_length: int = 0
    claim_count: int = 0
    covered_chars: int = 0
    content_chars: int = 0
    noise_chars: int = 0
    issues: list[Issue] = field(default_factory=list)
    uncovered: list[tuple[int, int]] = field(default_factory=list)

    @property
    def coverage_ratio(self) -> float:
        return self.covered_chars / self.content_chars if self.content_chars else 1.0

    @property
    def noise_ratio(self) -> float:
        return self.noise_chars / self.content_chars if self.content_chars else 0.0

    @property
    def ok(self) -> bool:
        return not any(issue.blocking for issue in self.issues)

    def summary(self) -> str:
        return (
            f"coverage {self.coverage_ratio:6.2%} ({self.covered_chars}/{self.content_chars}) | "
            f"noise {self.noise_ratio:6.2%} | claims {self.claim_count}"
        )


def numeric_tokens(text: str) -> Counter:
    """Numeric literals, for conservation checks.

    Deliberately dumb: a value that appears in generated acceptance criteria but not in
    the source was invented, and that is worth flagging even when it is plausible.
    """
    return Counter(_NUMERIC_RE.findall(text or ""))


def invented_numbers(source_text: str, generated_texts: list[str]) -> Counter:
    """Numbers present in generated text but absent from the source."""
    generated: Counter = Counter()
    for text in generated_texts:
        generated.update(numeric_tokens(text))
    return generated - numeric_tokens(source_text)


def verify_annotation(doc: str, annotation: Annotation) -> VerificationReport:
    report = VerificationReport(
        source_length=len(doc),
        claim_count=len(annotation.claims),
    )

    valid = [c for c in annotation.claims if _check_shape(c, doc, report)]
    _check_overlap(valid, report)
    _check_coverage(doc, valid, report)
    _check_noise_share(valid, len(doc), report)
    return report


def _check_shape(claim: Claim, doc: str, report: VerificationReport) -> bool:
    where = f"{claim.label}[{claim.start},{claim.end})"

    if claim.label not in LABELS:
        report.issues.append(Issue("unknown_label", f"{where}: unknown label {claim.label!r}"))
        return False
    if claim.start < 0 or claim.end > len(doc) or claim.start >= claim.end:
        report.issues.append(Issue("span_out_of_range", f"{where}: invalid range for source of length {len(doc)}"))
        return False
    if claim.quote and doc[claim.start : claim.end] != claim.quote:
        report.issues.append(
            Issue(
                "quote_mismatch",
                f"{where}: quote is not verbatim source text "
                f"(source={doc[claim.start : claim.end][:60]!r} quote={claim.quote[:60]!r}) "
                "- the model tried to rewrite instead of claim",
            )
        )
        return False
    return True


def _check_overlap(claims: list[Claim], report: VerificationReport) -> None:
    ordered = sorted(claims, key=lambda c: (c.start, c.end))
    for left, right in zip(ordered, ordered[1:]):
        if left.overlaps(right):
            report.issues.append(
                Issue(
                    "overlapping_claims",
                    f"{left.label}[{left.start},{left.end}) overlaps "
                    f"{right.label}[{right.start},{right.end}) - each character may hold one label",
                )
            )


def _check_coverage(doc: str, claims: list[Claim], report: VerificationReport) -> None:
    claimed = [False] * len(doc)
    for claim in claims:
        for index in range(claim.start, claim.end):
            claimed[index] = True
            if not doc[index].isspace():
                report.covered_chars += 1
            if claim.label == LABEL_NOISE and not doc[index].isspace():
                report.noise_chars += 1

    report.content_chars = sum(1 for ch in doc if not ch.isspace())
    report.uncovered = _uncovered_runs(doc, claimed)

    if report.uncovered:
        samples = "; ".join(_context(doc, start, end) for start, end in report.uncovered[:MAX_UNCOVERED_SAMPLES])
        more = ""
        if len(report.uncovered) > MAX_UNCOVERED_SAMPLES:
            more = f" (+{len(report.uncovered) - MAX_UNCOVERED_SAMPLES} more)"
        report.issues.append(
            Issue(
                "unclaimed_source",
                f"{len(report.uncovered)} source runs are claimed by nobody - "
                f"omissions surface here: {samples}{more}",
            )
        )


def _check_noise_share(claims: list[Claim], source_length: int, report: VerificationReport) -> None:
    if report.content_chars and report.noise_ratio > MAX_NOISE_RATIO:
        noise_samples = "; ".join(
            _context(doc_sample(claims, c.start, c.end), c.start, c.end)
            for c in claims
            if c.label == LABEL_NOISE
        )[: MAX_UNCOVERED_SAMPLES * 60]
        report.issues.append(
            Issue(
                "noise_too_large",
                f"{report.noise_ratio:.0%} of the source was declared noise (limit {MAX_NOISE_RATIO:.0%}) "
                f"- requirement text is probably being swallowed as noise: {noise_samples}",
                blocking=True,
            )
        )


def _uncovered_runs(doc: str, claimed: list[bool]) -> list[tuple[int, int]]:
    runs: list[tuple[int, int]] = []
    start: int | None = None
    for index, is_claimed in enumerate(claimed):
        meaningful = not doc[index].isspace()
        if meaningful and not is_claimed and start is None:
            start = index
        elif (not meaningful or is_claimed) and start is not None:
            runs.append((start, index))
            start = None
    if start is not None:
        runs.append((start, len(doc)))
    return runs


def _context(doc: str, start: int, end: int) -> str:
    left = max(0, start - CONTEXT_PADDING)
    right = min(len(doc), end + CONTEXT_PADDING)
    snippet = doc[left:right].replace("\n", "\\n")
    return f"[{start},{end}) ...{snippet}..."


def doc_sample(claims: list[Claim], start: int, end: int) -> str:
    """Noise claims carry their own quote, usable when the source is unavailable."""
    for claim in claims:
        if claim.start == start and claim.end == end and claim.quote:
            return claim.quote
    return ""


